"""
    Bubble Sort Algorithm

    :param nums_array: list
    :return nums_array: list
    """
def bubble_sort(nums_array: list) -> list {
    is_sorted = True;
    for i in range(0, (len(nums_array) - 1)) {
        for j in range(0, (len(nums_array) - i - 1)) {
            if (nums_array[j] > nums_array[(j + 1)]) {
                is_sorted = False;
                temp = nums_array[j];
                nums_array[j] = nums_array[(j + 1)];
                nums_array[(j + 1)] = temp;
            }
        }
        if is_sorted {
            break;
        }
    }
    return nums_array;
}

"""
	This is the help function to find the largest digit
	:param n  :(int) the number to find the largest digit
	:param lar:(int) found the largest digit
	:return   :(int) the largest digit
	"""
def find_largest_digit_helper(n: Any, lar: Any) -> object {
    if (n < lar) {
        return lar;
    } else {
        if ((n % 10) > lar) {
            lar = n % 10;
        }
        return find_largest_digit_helper(int((n / 10)), lar);
    }
}

